SELECT c.country, o.region, COUNT(*) AS n FROM db.orders o LEFT JOIN db.customers c ON o.customer_id = c.id GROUP BY c.country, o.region ORDER BY c.country, o.region;
SELECT d.id, d.region AS db_region, p.region AS prod_region FROM db.orders d JOIN prod.orders p ON d.id = p.id WHERE d.region <> p.region ORDER BY d.id;
SELECT COUNT(*) AS mismatched FROM db.orders d JOIN prod.orders p ON d.id = p.id WHERE d.region <> p.region;

